<?php

namespace App\Utility;

use RuntimeException;

//Resolves Vite-built asset URLs for use in PHP/CakePHP templates.
//Reads webroot/dist/.vite/manifest.json — generated by `vite build`.
//USAGE IN TEMPLATES
//==================
//CSS bundle:
//  echo ViteManifest::css('app-theme');        // <link rel="stylesheet" href="/dist/...">
//JS bundle (React app):
//  echo ViteManifest::script('app');           // <script type="module" src="/dist/...">
//Legacy JS bundle (global scope):
//  echo ViteManifest::legacyScript('legacy');  // <script src="/dist/...">
//MANIFEST ENTRY NAMES
//====================
//  'app'          → app/index.tsx                        (React app)
//  'app-theme'   → webroot/css/app-theme.js             (default.css + theme.css + home-themes.css)
//  'besogo-css'   → webroot/besogo/css/besogo-bundle.js  (besogo.css + board-flat.css)
//  'legacy'       → virtual:legacy-app                   (bundled app global JS)
//  'besogo'       → virtual:legacy-besogo               (bundled besogo viewer JS)
//  'sets-index'   → virtual:legacy-sets-index           (the code of the collections page)
//  'sets-view'    → virtual:legacy-sets-view            (the code of the page of a collection)
//  'play'         → virtual:legacy-play                 (the code of the play page)
//  'play-board'   → virtual:legacy-play-board           (the board of the play page, set up before the rest of the page)
//  'profile'      → virtual:legacy-profile              (the code of the profile page)
//  'schedule'     → virtual:legacy-schedule             (the code of the schedule page)
//  'time-mode'    → virtual:legacy-time-mode            (the code of the time mode overview and results)
//  'settings'     → virtual:legacy-settings             (the code of the settings page)
//  'problem-admin' → virtual:legacy-problem-admin       (the upload history, the tag overview and the similar problem search)
class ViteManifest
{
	//Cached manifest contents after first load
	private static ?array $manifest = null;

	//Path to the Vite manifest file (relative to webroot)
	private const MANIFEST_PATH = 'dist/.vite/manifest.json';

	//Map from logical entry name → source file key used in manifest.
	//These must match the `input` keys in vite.config.js.
	private const ENTRY_MAP = [
		'app'         => 'app/index.tsx',
		'app-theme'   => 'webroot/css/app-theme.js',
		'besogo-css'  => 'webroot/besogo/css/besogo-bundle.js',
		'legacy'      => 'virtual:legacy-app',
		'besogo'      => 'virtual:legacy-besogo',
		'play'        => 'virtual:legacy-play',
		'play-board'  => 'virtual:legacy-play-board',
		'profile'     => 'virtual:legacy-profile',
		'sets-index'  => 'virtual:legacy-sets-index',
		'sets-view'   => 'virtual:legacy-sets-view',
		'time-mode'   => 'virtual:legacy-time-mode',
		'schedule'    => 'virtual:legacy-schedule',
		'settings'    => 'virtual:legacy-settings',
		'problem-admin' => 'virtual:legacy-problem-admin',
	];

	//The <link> of a CSS bundle entry (e.g. 'app-theme')
	public static function css(string $entry): string
	{
		$built = self::built($entry);
		//A JS proxy entry keeps its CSS under 'css'
		return '<link rel="stylesheet" href="' . self::url($built['css'][0] ?? $built['file']) . '" />';
	}

	//A plain <script> (no type="module") of a legacy global-scope bundle (e.g. 'legacy'), whose functions stay global
	public static function legacyScript(string $entry): string
	{
		return '<script src="' . self::url(self::built($entry)['file']) . '"></script>';
	}

	//A <script type="module"> of a JS entry (e.g. 'app')
	public static function script(string $entry): string
	{
		return '<script type="module" src="' . self::url(self::built($entry)['file']) . '"></script>';
	}

	//What the build made of an entry; a name that isn't one, or an entry the build is missing, is an error,
	//as the page would otherwise go without its script
	/** @return array{file: string, css?: list<string>} */
	private static function built(string $entry): array
	{
		if (!isset(self::ENTRY_MAP[$entry]))
			throw new RuntimeException("Unknown Vite entry '$entry', see ViteManifest::ENTRY_MAP.");
		$built = self::load()[self::ENTRY_MAP[$entry]] ?? null;
		if (!isset($built['file']))
			throw new RuntimeException("The Vite manifest has no '" . self::ENTRY_MAP[$entry] . "'. Run `pnpm build`.");
		return $built;
	}

	private static function url(string $file): string
	{
		return htmlspecialchars('/dist/' . $file, ENT_QUOTES, 'UTF-8');
	}

	//Load and cache the Vite manifest. Throws if manifest is not found.
	private static function load(): array
	{
		if (self::$manifest !== null)
			return self::$manifest;

		$path = WWW_ROOT . str_replace('/', DS, self::MANIFEST_PATH);

		if (!file_exists($path))
			throw new RuntimeException('Vite manifest not found at ' . $path . '. Run `pnpm build`.');

		$json = file_get_contents($path);
		if ($json === false)
			throw new RuntimeException('Failed to read Vite manifest at ' . $path);

		self::$manifest = json_decode($json, true) ?? [];
		return self::$manifest;
	}
}
